static inline uint8_t geoByte(const uint32_t* data,uint16_t i){
  uint32_t word=pgm_read_dword(data+(i>>2));
  return (uint8_t)(word>>((i&3u)*8u));
}
static inline uint16_t geoU16(const uint32_t* data,uint16_t i){
  uint16_t a=geoByte(data,(uint16_t)(i*2u));
  return a | (uint16_t(geoByte(data,(uint16_t)(i*2u+1u)))<<8);
}
static inline uint16_t geoRow(int row){return geoU16(kGeoRows32,(uint16_t)row);}
static inline uint8_t geoRun(int index){return geoByte(kGeoRuns32,(uint16_t)index);}
static inline uint16_t geoBorderRow(int row){return geoU16(kGeoBordersRows32,(uint16_t)row);}
static inline uint8_t geoBorder(int index){return geoByte(kGeoBorders32,(uint16_t)index);}
